SELECT json_build_object('fact','fato_itens_pedido','silver_rows',(SELECT count(*) FROM silver."olist_order_items_dataset"),'rows',count(*),'money',json_build_object('price',sum("price")::text,'freight_value',sum("freight_value")::text),'fk_members',json_build_object('cliente_sk',json_build_object('nao_informado',count(*) FILTER(WHERE "cliente_sk"=-1),'referencia_nao_encontrada',count(*) FILTER(WHERE "cliente_sk"=-2)),'localizacao_sk',json_build_object('nao_informado',count(*) FILTER(WHERE "localizacao_sk"=-1),'referencia_nao_encontrada',count(*) FILTER(WHERE "localizacao_sk"=-2)),'produto_sk',json_build_object('nao_informado',count(*) FILTER(WHERE "produto_sk"=-1),'referencia_nao_encontrada',count(*) FILTER(WHERE "produto_sk"=-2)),'vendedor_sk',json_build_object('nao_informado',count(*) FILTER(WHERE "vendedor_sk"=-1),'referencia_nao_encontrada',count(*) FILTER(WHERE "vendedor_sk"=-2)),'data_compra_sk',json_build_object('nao_informado',count(*) FILTER(WHERE "data_compra_sk"=-1),'referencia_nao_encontrada',count(*) FILTER(WHERE "data_compra_sk"=-2)),'data_limite_envio_sk',json_build_object('nao_informado',count(*) FILTER(WHERE "data_limite_envio_sk"=-1),'referencia_nao_encontrada',count(*) FILTER(WHERE "data_limite_envio_sk"=-2))),'fingerprint',encode(sha256(convert_to(string_agg(row_to_json(x)::text,'' ORDER BY "order_id","order_item_id"),'UTF8')),'hex')) FROM (SELECT "order_id","order_item_id","product_id","seller_id","shipping_limit_date","price","freight_value","customer_id","order_status","order_purchase_timestamp","cliente_sk","localizacao_sk","produto_sk","vendedor_sk","data_compra_sk","data_limite_envio_sk" FROM gold."fato_itens_pedido") x;
SELECT json_build_object('fact','fato_itens_pedido','statuses',json_object_agg(order_status,n)) FROM (SELECT order_status,count(*) n FROM gold."fato_itens_pedido" GROUP BY order_status) q;
SELECT json_build_object('fact','fato_pagamentos','silver_rows',(SELECT count(*) FROM silver."olist_order_payments_dataset"),'rows',count(*),'money',json_build_object('payment_value',sum("payment_value")::text),'fk_members',json_build_object('cliente_sk',json_build_object('nao_informado',count(*) FILTER(WHERE "cliente_sk"=-1),'referencia_nao_encontrada',count(*) FILTER(WHERE "cliente_sk"=-2)),'localizacao_sk',json_build_object('nao_informado',count(*) FILTER(WHERE "localizacao_sk"=-1),'referencia_nao_encontrada',count(*) FILTER(WHERE "localizacao_sk"=-2)),'forma_pagamento_sk',json_build_object('nao_informado',count(*) FILTER(WHERE "forma_pagamento_sk"=-1),'referencia_nao_encontrada',count(*) FILTER(WHERE "forma_pagamento_sk"=-2)),'data_compra_sk',json_build_object('nao_informado',count(*) FILTER(WHERE "data_compra_sk"=-1),'referencia_nao_encontrada',count(*) FILTER(WHERE "data_compra_sk"=-2))),'fingerprint',encode(sha256(convert_to(string_agg(row_to_json(x)::text,'' ORDER BY "order_id","payment_sequential"),'UTF8')),'hex')) FROM (SELECT "order_id","payment_sequential","payment_type","payment_installments","payment_value","customer_id","order_status","order_purchase_timestamp","cliente_sk","localizacao_sk","forma_pagamento_sk","data_compra_sk" FROM gold."fato_pagamentos") x;
SELECT json_build_object('fact','fato_pagamentos','statuses',json_object_agg(order_status,n)) FROM (SELECT order_status,count(*) n FROM gold."fato_pagamentos" GROUP BY order_status) q;
SELECT json_build_object('reconciliation_orders',count(*),'without_items',count(*) FILTER(WHERE itens IS NULL),'without_payments',count(*) FILTER(WHERE pagamentos IS NULL),'compared',count(diferenca),'over_one_cent',count(*) FILTER(WHERE abs(diferenca)>0.01),'positive',count(*) FILTER(WHERE diferenca>0.01),'negative',count(*) FILTER(WHERE diferenca < -0.01),'min_delta',min(diferenca)::text,'max_delta',max(diferenca)::text) FROM (WITH i AS (SELECT order_id,count(*) itens,sum(price) preco,sum(freight_value) frete FROM gold."fato_itens_pedido" GROUP BY order_id),
p AS (SELECT order_id,count(*) pagamentos,sum(payment_value) valor FROM gold."fato_pagamentos" GROUP BY order_id)
SELECT o.order_id,o.order_status,i.itens,p.pagamentos,i.preco,i.frete,p.valor,
 CASE WHEN i.order_id IS NULL OR p.order_id IS NULL THEN NULL ELSE p.valor-i.preco-i.frete END diferenca
FROM gold."fato_pedidos" o LEFT JOIN i ON i.order_id=o.order_id LEFT JOIN p ON p.order_id=o.order_id) rec;
SELECT json_build_object('divergent_status',order_status,'orders',count(*)) FROM (WITH i AS (SELECT order_id,count(*) itens,sum(price) preco,sum(freight_value) frete FROM gold."fato_itens_pedido" GROUP BY order_id),
p AS (SELECT order_id,count(*) pagamentos,sum(payment_value) valor FROM gold."fato_pagamentos" GROUP BY order_id)
SELECT o.order_id,o.order_status,i.itens,p.pagamentos,i.preco,i.frete,p.valor,
 CASE WHEN i.order_id IS NULL OR p.order_id IS NULL THEN NULL ELSE p.valor-i.preco-i.frete END diferenca
FROM gold."fato_pedidos" o LEFT JOIN i ON i.order_id=o.order_id LEFT JOIN p ON p.order_id=o.order_id) rec WHERE abs(diferenca)>0.01 GROUP BY order_status ORDER BY order_status;
